/**
 * What Today draws about streak freeze (SRS v2 phase E), all of it local:
 * meta `srs` says whether the feature shows, meta `streak` holds the switch,
 * the freezes ready and the days a freeze covered.
 */
import { effectiveStreak } from '@lexpad/core';
import { loadStreak } from '@/db/repo.js';
import { loadSrsView, shows } from '@/features/schedule/data.js';

/** Streak freeze as Today shows it; `on` false means Today is exactly as before. */
export interface FreezeView {
  on: boolean;
  /**
   * The feature is switched on for the account but freeze is off: the chip
   * opens the sheet anyway, which says freezes exist and offers to turn
   * them on (SRS v2 access proposal 4). False whenever `on` is.
   */
  offered: boolean;
  freezes: number;
  /** Days a freeze covered, for the week strip's dotted ring. */
  frozenDays: ReadonlySet<number>;
  /** The streak shown, with freezes pending counted. */
  current: number;
}

export const FREEZE_OFF: FreezeView = {
  on: false,
  offered: false,
  freezes: 0,
  frozenDays: new Set(),
  current: 0,
};

/** Reads streak freeze for today's day index. */
export async function loadFreeze(today: number): Promise<FreezeView> {
  const [srs, streak] = await Promise.all([loadSrsView(), loadStreak()]);
  if (!shows(srs, 'streakFreeze')) return FREEZE_OFF;
  if (streak.freezeOn !== true)
    return { ...FREEZE_OFF, offered: true, current: effectiveStreak(streak, today) };
  return {
    on: true,
    offered: false,
    freezes: streak.freezes ?? 0,
    frozenDays: new Set(streak.frozenDays ?? []),
    current: effectiveStreak(streak, today),
  };
}
